23	export const scoreArmy = (army: Card[]): number => {
24	  const typeCount = countDistinctMonsterTypes(army);
25	  const richestThresholdMet = SCORE_THRESHOLDS_RICHEST_FIRST.find(
26	    ({ atLeastTypes }) => typeCount >= atLeastTypes,
27	  );
28	
29	  const scorePerSphinx = richestThresholdMet?.score ?? BASE_SPHINX_SCORE;
30	  const sphinxCount = army.filter(isSphinx).length;
31	  return scorePerSphinx * sphinxCount;
32	};
